<style>
@page{size:A4 portrait;margin:12mm}*{box-sizing:border-box}body{margin:0;background:#eeeae3;color:#30271e;font:11px/1.5 Arial,DejaVu Sans,sans-serif}.document{max-width:186mm;margin:20px auto;padding:12mm;background:#fff}.doc-header{width:100%;border-collapse:collapse;border-bottom:2px solid #b98c45;margin-bottom:16px}.doc-header td{padding:0 0 14px;vertical-align:top}.doc-logo{width:72px;height:72px;object-fit:contain}.doc-company{font-size:18px;font-weight:bold;margin-bottom:5px}.doc-meta{text-align:right;width:30%}.doc-meta strong{font-size:18px;text-transform:uppercase}.doc-info{width:100%;border-spacing:0;margin-bottom:14px;table-layout:fixed}.doc-info td{width:50%;vertical-align:top;padding:12px;background:#f7f0e6;border:4px solid white;border-radius:8px;overflow-wrap:anywhere}.doc-info h2,.doc-box h2{font-size:12px;margin:0 0 5px}.doc-lines{width:100%;border-collapse:collapse;table-layout:fixed}.doc-lines th{background:#f7f0e6;font-size:10px;text-align:left}.doc-lines td,.doc-lines th{padding:8px 5px;border-bottom:1px solid #dfcfb7;vertical-align:top;overflow-wrap:anywhere}.doc-lines thead{display:table-header-group}.doc-lines tr{page-break-inside:avoid}.doc-lines th:nth-child(1){width:10%}.doc-lines th:nth-child(2){width:15%}.doc-lines th:nth-child(3){width:33%}.doc-lines th:nth-child(4){width:8%}.doc-lines th:nth-child(n+5){width:17%}.doc-product-image{display:block;width:44px;height:44px;border:1px solid #dfcfb7;border-radius:4px}.doc-product-no-image{display:block;width:44px;min-height:44px;padding-top:12px;text-align:center;font-size:8px;color:#776b5d;background:#f7f0e6;border:1px solid #dfcfb7;border-radius:4px}.money{text-align:right!important}.doc-totals{width:45%;margin:14px 0 16px auto;border-collapse:collapse;page-break-inside:avoid}.doc-totals td{padding:5px;border-bottom:1px solid #dfcfb7}.doc-totals tr:last-child{font-size:14px;font-weight:bold}.doc-box{background:#f7f0e6;padding:12px;border-radius:8px;margin:12px 0;page-break-inside:avoid}.doc-footer{border-top:1px solid #b98c45;padding-top:10px;margin-top:22px;font-size:10px}.doc-notice{font-size:10px;margin:10px 0}.doc-toolbar{max-width:186mm;margin:15px auto;display:flex;gap:14px;align-items:center}.doc-toolbar button{background:#8e0718;color:white;border:0;border-radius:4px;padding:10px 16px;cursor:pointer}small{font-size:9px}p{margin:4px 0}h1{margin:0;font-size:18px}@media print{body{background:white}.document{margin:0;padding:0;max-width:none}.doc-toolbar{display:none}body{-webkit-print-color-adjust:exact;print-color-adjust:exact}}@media screen and (max-width:600px){.document{margin:0;padding:14px}.doc-company{font-size:15px}.doc-logo{width:50px;height:50px}.doc-meta strong{font-size:14px}.doc-totals{width:65%}}
.doc-order-reference{font-size:14px;font-weight:700;text-transform:uppercase}
</style>